package demo.pharma.inventory;
import demo.pharma.audit.AuditService; import demo.pharma.catalog.*; import demo.pharma.common.exception.*; import demo.pharma.common.web.PageResponse; import demo.pharma.supplier.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import lombok.*; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.math.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/batches") @RequiredArgsConstructor public class BatchController {private final MedicineBatchRepository batches;private final MedicineRepository medicines;private final SupplierRepository suppliers;private final InventoryService inventory;private final AuditService audit;
 record Request(@NotNull UUID medicineId,@NotBlank String batchNumber,LocalDate manufacturingDate,@NotNull LocalDate expiryDate,@NotNull@PositiveOrZero BigDecimal purchasePrice,@NotNull@PositiveOrZero BigDecimal mrp,@NotNull@PositiveOrZero BigDecimal sellingPrice,@PositiveOrZero BigDecimal openingQuantity,UUID supplierId){}record UpdateRequest(LocalDate manufacturingDate,@NotNull LocalDate expiryDate,@NotNull@PositiveOrZero BigDecimal purchasePrice,@NotNull@PositiveOrZero BigDecimal mrp,@NotNull@PositiveOrZero BigDecimal sellingPrice){}record View(UUID id,UUID medicineId,String medicineName,String batchNumber,LocalDate manufacturingDate,LocalDate expiryDate,BigDecimal purchasePrice,BigDecimal mrp,BigDecimal sellingPrice,BigDecimal quantity,BigDecimal reservedQuantity,UUID supplierId){}
 @GetMapping @PreAuthorize("hasAuthority('BATCH_VIEW')")PageResponse<View> list(@RequestParam(required=false)UUID medicineId,@RequestParam(required=false)Boolean expired,@PageableDefault(size=20,sort="expiryDate")Pageable p){return PageResponse.of(batches.findAll((r,q,b)->{var x=b.conjunction();if(medicineId!=null)x=b.and(x,b.equal(r.get("medicine").get("id"),medicineId));if(Boolean.TRUE.equals(expired))x=b.and(x,b.lessThan(r.get("expiryDate"),LocalDate.now()));return x;},p).map(this::v));}@GetMapping("/{id}")@PreAuthorize("hasAuthority('BATCH_VIEW')")View get(@PathVariable UUID id){return v(find(id));}@PostMapping@PreAuthorize("hasAuthority('BATCH_CREATE')")@Transactional View create(@Valid@RequestBody Request r){validateDates(r.manufacturingDate(),r.expiryDate());MedicineBatch b=new MedicineBatch();b.setMedicine(medicines.findById(r.medicineId()).orElseThrow(()->new NotFoundException("Medicine",r.medicineId())));b.setSupplier(r.supplierId()==null?null:suppliers.findById(r.supplierId()).orElseThrow(()->new NotFoundException("Supplier",r.supplierId())));b.setBatchNumber(r.batchNumber().trim());b.setManufacturingDate(r.manufacturingDate());b.setExpiryDate(r.expiryDate());b.setPurchasePrice(r.purchasePrice());b.setMrp(r.mrp());b.setSellingPrice(r.sellingPrice());b.setQuantity(BigDecimal.ZERO);b=batches.save(b);if(r.openingQuantity()!=null&&r.openingQuantity().signum()>0)inventory.adjust(b.getId(),r.openingQuantity(),MovementType.ADJUSTMENT_IN,"Opening balance");audit.logCurrent("BATCH_CREATED","MEDICINE_BATCH",b.getId(),null,b.getBatchNumber());return v(find(b.getId()));}@PutMapping("/{id}")@PreAuthorize("hasAuthority('BATCH_UPDATE')")@Transactional View update(@PathVariable UUID id,@Valid@RequestBody UpdateRequest r){MedicineBatch b=find(id);validateDates(r.manufacturingDate(),r.expiryDate());b.setManufacturingDate(r.manufacturingDate());b.setExpiryDate(r.expiryDate());b.setPurchasePrice(r.purchasePrice());b.setMrp(r.mrp());b.setSellingPrice(r.sellingPrice());batches.save(b);audit.logCurrent("BATCH_UPDATED","MEDICINE_BATCH",id,null,b.getBatchNumber());return v(b);}private void validateDates(LocalDate m,LocalDate e){if(m!=null&&!e.isAfter(m))throw new BusinessException("Expiry date must be after manufacturing date");}private MedicineBatch find(UUID id){return batches.findById(id).orElseThrow(()->new NotFoundException("Batch",id));}private View v(MedicineBatch b){return new View(b.getId(),b.getMedicine().getId(),b.getMedicine().getName(),b.getBatchNumber(),b.getManufacturingDate(),b.getExpiryDate(),b.getPurchasePrice(),b.getMrp(),b.getSellingPrice(),b.getQuantity(),b.getReservedQuantity(),b.getSupplier()==null?null:b.getSupplier().getId());}}
